import 'package:flutter/material.dart';
import '../../services/belanjaku/delivery_area_service.dart';
class BelanjakuDeliveryAreaScreen extends StatelessWidget { const BelanjakuDeliveryAreaScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Pilih Wilayah')), body: StreamBuilder<List<Map<String, dynamic>>>(stream: BelanjakuDeliveryAreaService().watchActiveAreas(), builder: (context, snap) { if (snap.hasError) return const Center(child: Text('Wilayah belum dapat dimuat.')); if (!snap.hasData) return const Center(child: CircularProgressIndicator()); final list = snap.data!; if (list.isEmpty) return const Center(child: Padding(padding: EdgeInsets.all(24), child: Text('Wilayah layanan belum diatur admin.', textAlign: TextAlign.center))); return ListView.separated(itemCount: list.length, separatorBuilder: (_, __) => const Divider(height: 1), itemBuilder: (context, i) { final a = list[i]; final name = a['name'] as String? ?? 'Wilayah'; final sub = a['subdistrict'] as String? ?? ''; return ListTile(leading: const Icon(Icons.location_on_outlined, color: Color(0xFF0866D9)), title: Text(name), subtitle: sub.isEmpty ? null : Text(sub), onTap: () => Navigator.pop(context, <String, String>{'id': a['id'] as String, 'name': name, 'subdistrict': sub})); }); })); }
